11	// Author: Gu, Zihan
12	// Description:
13	`timescale 1ns/1ns
14	//`include "IDecode_define.v"
15	`include "define.v"
16	
17	module  csrfile(
18	  input                           clk                             ,
19	  input                           rst_n                           ,
20	
21	  //control signal
22	  input   [31:0]                  ctrl_inst_i                     ,
23	  input   [1:0]                   ctrl_csr_i                      ,
24	  input                           ctrl_custom_signal_0_i          ,
25	  input                           ctrl_isvec_i                    ,
26	
27	  input   [`XLEN-1:0]             in1_i                           ,
28	  input                           write_i                         ,
29	
30	  //CTA2csr
31	  input                           CTA2csr_valid_i                 ,
32	  input   [`WF_COUNT_WIDTH-1:0]   dispatch2cu_wg_wf_count_i       ,
33	  input   [`WAVE_ITEM_WIDTH-1:0]  dispatch2cu_wf_size_dispatch_i  ,
34	  input   [`SGPR_ID_WIDTH:0]      dispatch2cu_sgpr_base_dispatch_i,
35	  input   [`VGPR_ID_WIDTH:0]      dispatch2cu_vgpr_base_dispatch_i,
36	  input   [`TAG_WIDTH-1:0]        dispatch2cu_wf_tag_dispatch_i   ,
37	  input   [`LDS_ID_WIDTH:0]       dispatch2cu_lds_base_dispatch_i ,
38	  //input   [`MEM_ADDR_WIDTH-1:0]   dispatch2cu_start_pc_dispatch_i ,
39	  input   [`MEM_ADDR_WIDTH-1:0]   dispatch2cu_pds_base_dispatch_i ,
40	  //input   [`MEM_ADDR_WIDTH-1:0]   dispatch2cu_gds_base_dispatch_i ,
41	  input   [`MEM_ADDR_WIDTH-1:0]   dispatch2cu_csr_knl_dispatch_i  ,
42	  input   [`WG_SIZE_X_WIDTH-1:0]  dispatch2cu_wgid_x_dispatch_i   ,
43	  input   [`WG_SIZE_Y_WIDTH-1:0]  dispatch2cu_wgid_y_dispatch_i   ,
44	  input   [`WG_SIZE_Z_WIDTH-1:0]  dispatch2cu_wgid_z_dispatch_i   ,
45	  input   [31:0]                  dispatch2cu_wg_id_i             ,
46	  //input   [`DEPTH_WARP-1:0]       wid_i                           ,
47	
48	  output  [`XLEN-1:0]             wb_wxd_rd_o                     ,
49	  output  [2:0]                   frm_o                           ,
50	  output  [`SGPR_ID_WIDTH:0]      sgpr_base_o                     ,
51	  output  [`VGPR_ID_WIDTH:0]      vgpr_base_o                     ,
52	  output  [`XLEN-1:0]             simt_rpc_o                      ,
53	  output  [`XLEN-1:0]             lsu_tid_o                       ,
54	  output  [`XLEN-1:0]             lsu_pds_o                       ,
55	  output  [`XLEN-1:0]             lsu_numw_o                      
56	  );
57	  // Machine Trap-Vector Base-Address Register (mtvec)
58	  reg [`XLEN-1:0] mtvec;
59	  // Machine Interrupt Registers (mip and mie)
60	  reg             mtip;// timer interrupt-pending bits
61	  reg             stip;
62	  reg             utip;
63	  reg             mtie;// timer interrupt-enable bits
64	  reg             stie;
65	  reg             utie;
66	  reg             msip;// software interrupt-pending bits
67	  reg             ssip;
68	  reg             usip;
69	  reg             msie;// software interrupt-enable bits
70	  reg             ssie;
71	  reg             usie;
72	  reg             meip;// external interrupt-pending bits
73	  reg             seip;
74	  reg             ueip;
75	  reg             meie;// external interrupt-enable bits
76	  reg             seie;
77	  reg             ueie;
78	  reg [`XLEN-1:0] mip;
79	  reg [`XLEN-1:0] mie;
80	
81	  
82	  reg             mie_bit;// interrupt-enable bit
83	  reg             sie;
84	  reg             uie;
85	  reg             mpie;// to support nested tarps
86	  reg             spie;
87	  reg             upie;
88	  reg [1:0]       mpp;
89	  reg             spp;
90	  reg             mprv;// memory privilege
91	  reg             mxr;
92	  reg             sum;
93	  reg             tvm;
94	  reg             tw;
95	  reg             tsr;
96	  reg [1:0]       fs;// extension context status
97	  reg [1:0]       xs;
98	  reg             sd;//   state dirty
99	  reg [`XLEN-1:0] mstatus;
100	
101	  // Machine Scratch Register (mscratch)
102	  reg [`XLEN-1:0] mscratch;
103	
104	  // Machine Exception Program Counter (mepc)
105	  reg [`XLEN-1:0] mepc;
106	
107	  // Machine Cause Register (mcause)
108	  reg [`XLEN-1:0] mcause;
109	
110	  // Machine Trap Value Register (mtval)
111	  reg [`XLEN-1:0] mtval;
112	
113	  // thread message register
114	  reg [`XLEN-1:0]             threadid;
115	  reg [`WF_COUNT_WIDTH-1:0]   wg_wf_count;
116	  reg [`WAVE_ITEM_WIDTH-1:0]  wf_size_dispatch;
117	  reg [`MEM_ADDR_WIDTH-1:0]   knl_base;
118	  reg [31:0]                  wg_id;
119	  reg [`TAG_WIDTH-1:0]        wf_tag_dispatch;
120	  reg [`MEM_ADDR_WIDTH-1:0]   lds_base_dispatch;
121	  reg [`MEM_ADDR_WIDTH-1:0]   pds_baseaddr;
122	  reg [`WG_SIZE_X_WIDTH-1:0]  wg_id_x;
123	  reg [`WG_SIZE_Y_WIDTH-1:0]  wg_id_y;
124	  reg [`WG_SIZE_Z_WIDTH-1:0]  wg_id_z;
125	  reg [31:0]                  csr_print;
126	  reg [31:0]                  rpc;
127	  reg [`SGPR_ID_WIDTH:0]      sgpr_base_dispatch;
128	  reg [`VGPR_ID_WIDTH:0]      vgpr_base_dispatch;
129	  wire [31:0]                 lds_base_dispatch_h;
130	
131	  // float csr address
132	  reg             nv;
133	  reg             dz;
134	  reg             of;
135	  reg             uf;
136	  reg             nx;
137	  reg [4:0]       fflags;
138	  reg [2:0]       frm;
139	  reg [`XLEN-1:0] fcsr;
140	
141	  // Vector csr address
142	  reg                         vill;
143	  reg                         vma;
144	  reg                         vta;//undisturbed
145	  reg [2:0]                   vsew;//only support e32
146	  reg [2:0]                   vlmul;//only support LMUL=1
147	  reg [`XLEN-1:0]             vlmax;
148	  //reg [`XLEN-1:0]             vstart;
149	  //reg                         vxsat;//fix-point accrued saturation flag
150	  //reg [1:0]                   vxrm;//fix point rounding mode
151	  //reg [`XLEN-1:0]             vcsr;
152	  //reg [`XLEN-1:0]             vl;
153	  reg [`XLEN-1:0]             vtype;
154	  //reg [`XLEN-1:0]             vlenb;
155	
156	  wire  [11:0]                csr_addr;
157	  wire  [`XLEN-1:0]           csr_input;
158	  wire                        wen;
159	  wire  [`XLEN-1:0]           wdata;
160	  reg   [`XLEN-1:0]           csr_rdata;
161	  reg   [`XLEN-1:0]           csr_wdata;
162	
163	  assign csr_addr = ctrl_inst_i[31:20];
164	  assign csr_input = in1_i;
165	  assign wdata = (wen & ctrl_custom_signal_0_i) ? csr_input : 
166	                 ((wen & ctrl_isvec_i) ? ((csr_input < vlmax) ? csr_input : vlmax) : csr_rdata);
167	  assign wen = (|ctrl_csr_i) & write_i;
168	  assign lds_base_dispatch_h = 32'h70000000;
169	  
170	  always@(*) begin
171	    case(ctrl_csr_i)
172	      2'b01   : csr_wdata = csr_input;
173	      2'b10   : csr_wdata = csr_rdata | csr_input;
174	      2'b11   : csr_wdata = csr_rdata & (~csr_input);
175	      default : csr_wdata = 'd0;
176	    endcase
177	  end
178	
179	  always@(*) begin
180	    case(csr_addr)
181	      `CSR_MSTATUS            : csr_rdata = mstatus;
182	      `CSR_MIE                : csr_rdata = mie;
183	      `CSR_MTVEC              : csr_rdata = mtvec;
184	      `CSR_MSCRATCH           : csr_rdata = mscratch;
185	      `CSR_MEPC               : csr_rdata = mepc;
186	      `CSR_MCAUSE             : csr_rdata = mcause;
187	      `CSR_MTVAL              : csr_rdata = mtval;
188	      `CSR_MIP                : csr_rdata = mip;
189	      `CSR_FRM                : csr_rdata = frm;
190	      `CSR_FCSR               : csr_rdata = fcsr;
191	      `CSR_FFLAGS             : csr_rdata = fflags;
192	      `CSR_VTYPE              : csr_rdata = vtype;
193	      `CSR_THREADID           : csr_rdata = threadid;
194	      `CSR_WG_WF_COUNT        : csr_rdata = wg_wf_count;
195	      `CSR_WF_SIZE_DISPATCH   : csr_rdata = wf_size_dispatch;
196	      `CSR_KNL_BASE           : csr_rdata = knl_base;
197	      `CSR_WG_ID              : csr_rdata = wg_id;
198	      `CSR_WF_TAG_DISPATCH    : csr_rdata = wf_tag_dispatch;
199	      `CSR_LDS_BASE_DISPATCH  : csr_rdata = lds_base_dispatch;
200	      `CSR_PDS_BASEADDR       : csr_rdata = pds_baseaddr;
201	      `CSR_WG_ID_X            : csr_rdata = wg_id_x;
202	      `CSR_WG_ID_Y            : csr_rdata = wg_id_y;
203	      `CSR_WG_ID_Z            : csr_rdata = wg_id_z;
204	      `CSR_PRINT              : csr_rdata = csr_print;
205	      `CSR_RPC                : csr_rdata = rpc;
206	      default                 : csr_rdata = 'd0;
207	    endcase
208	  end
209	
210	  //output
211	  assign wb_wxd_rd_o  = wdata;
212	  assign simt_rpc_o   = rpc;
213	  assign sgpr_base_o  = sgpr_base_dispatch;
214	  assign vgpr_base_o  = vgpr_base_dispatch;
215	  assign frm_o        = frm;
216	  assign lsu_tid_o    = wf_tag_dispatch * `NUM_THREAD;
217	  assign lsu_pds_o    = pds_baseaddr;
218	  assign lsu_numw_o   = wg_wf_count;
219	
220	  //rpc,csr_print
221	  always @(posedge clk or negedge rst_n) begin
222	    if(!rst_n) begin
223	      rpc       <= 'd0;
224	      csr_print <= 'd0;
225	    end
226	    else if(wen & ctrl_custom_signal_0_i) begin
227	      rpc       <= csr_input;
228	    end
229	    else if(wen & csr_addr == `CSR_PRINT) begin
230	      csr_print <= csr_wdata;
231	    end
232	    else begin
233	      rpc       <= rpc;
234	      csr_print <= csr_print;
235	    end
236	  end
237	  
238	  //mie and mip 
239	  always @(posedge clk or negedge rst_n) begin
240	    if(!rst_n) begin
241	      mtip <= 'd0;
242	      stip <= 'd0;
243	      utip <= 'd0;
244	      mtie <= 'd0;
245	      stie <= 'd0;
246	      utie <= 'd0;
247	      msip <= 'd0;
248	      ssip <= 'd0;
249	      usip <= 'd0;
250	      msie <= 'd0;
251	      ssie <= 'd0;
252	      usie <= 'd0;
253	      meip <= 'd0;
254	      seip <= 'd0;
255	      ueip <= 'd0;
256	      meie <= 'd0;
257	      seie <= 'd0;
258	      ueie <= 'd0;
259	    end
260	    else if(wen & csr_addr == `CSR_MIP) begin
261	      mtip <= csr_wdata[7];
262	      stip <= 'd0;
263	      utip <= 'd0;
264	      msip <= csr_wdata[3];
265	      ssip <= 'd0;
266	      usip <= 'd0;
267	      meip <= csr_wdata[11];
268	      seip <= 'd0;
269	      ueip <= 'd0;
270	    end
271	    else if(wen & csr_addr == `CSR_MIE) begin
272	      mtie <= csr_wdata[7];
273	      stie <= 'd0;
274	      utie <= 'd0;
275	      msie <= csr_wdata[3];
276	      ssie <= 'd0;
277	      usie <= 'd0;
278	      meie <= csr_wdata[11];
279	      seie <= 'd0;
280	      ueie <= 'd0;
281	    end
282	    else begin
283	      mtip <= mtip;
284	      stip <= stip;
285	      utip <= utip;
286	      mtie <= mtie;
287	      stie <= stie;
288	      utie <= utie;
289	      msip <= msip;
290	      ssip <= ssip;
291	      usip <= usip;
292	      msie <= msie;
293	      ssie <= ssie;
294	      usie <= usie;
295	      meip <= meip;
296	      seip <= seip;
297	      ueip <= ueip;
298	      meie <= meie;
299	      seie <= seie;
300	      ueie <= ueie;
301	    end
302	  end
303	
304	  always @(*) begin
305	      mip  = {{(`XLEN-12){1'b0}},meip,1'b0,seip,ueip,mtip,1'b0,stip,utip,msip,1'b0,ssip,usip};
306	      mie  = {{(`XLEN-12){1'b0}},meie,1'b0,seie,ueie,mtie,1'b0,stie,utie,msie,1'b0,ssie,usie};
307	  end
308	
309	  //mstatus
310	  always @(posedge clk or negedge rst_n) begin
311	    if(!rst_n) begin
312	      mie_bit  <= 'd0;
313	      sie  <= 'd0;
314	      uie  <= 'd0;
315	      mpie <= 'd0;
316	      spie <= 'd0;
317	      upie <= 'd0;
318	      mpp  <= 'd0;
319	      spp  <= 'd0;
320	      mprv <= 'd0;
321	      mxr  <= 'd0;
322	      sum  <= 'd0;
323	      tvm  <= 'd0;
324	      tw   <= 'd0;
325	      tsr  <= 'd0;
326	      fs   <= 'd0;
327	      xs   <= 'd0;
328	      sd   <= 'd0;
329	    end
330	    else if(wen & csr_addr == `CSR_MSTATUS) begin
331	      mie_bit <= csr_wdata[3];
332	      mpie    <= csr_wdata[7];
333	      mpp     <= 2'd3;
334	    end
335	    else begin
336	      mie_bit  <= mie_bit;
337	      sie  <= sie;
338	      uie  <= uie;
339	      mpie <= mpie;
340	      spie <= spie;
341	      upie <= upie;
342	      mpp  <= 2'd3;
343	      spp  <= spp;
344	      mprv <= mprv;
345	      mxr  <= mxr;
346	      sum  <= sum;
347	      tvm  <= tvm;
348	      tw   <= tw;
349	      tsr  <= tsr;
350	      fs   <= fs;
351	      xs   <= xs;
352	      sd   <= sd;
353	    end
354	  end
355	
356	  always @(*) begin
357	    mstatus = {sd,8'd0,tsr,tw,tvm,mxr,sum,mprv,xs,fs,mpp,2'd0,spp,mpie,1'b0,spie,upie,mie_bit,1'b0,sie,uie};
358	  end
359	
360	  //mscratch,mepc,mcause,mtval
361	  always @(posedge clk or negedge rst_n) begin
362	    if(!rst_n) begin
363	      mscratch <= 'd0;
364	      mepc     <= 'd0;
365	      mcause   <= 'd0;
366	      mtval    <= 'd0;
367	      mtvec    <= 'd0;
368	    end
369	    else if(wen & csr_addr == `CSR_MSCRATCH) begin
370	      mscratch <= csr_wdata;
371	    end
372	    else if(wen & csr_addr == `CSR_MEPC) begin
373	      mepc     <= csr_wdata;
374	    end
375	    else if(wen & csr_addr == `CSR_MCAUSE) begin
376	      mcause   <= csr_wdata;
377	    end
378	    else if(wen & csr_addr == `CSR_MTVAL) begin
379	      mtval    <= csr_wdata;
380	    end
381	    else begin
382	      mscratch <= mscratch;
383	      mepc     <= mepc;
384	      mcause   <= mcause;
385	      mtval    <= mtval;
386	      mtvec    <= 'd0;
387	    end
388	  end
389	
390	  //thread message register
391	  always @(posedge clk or negedge rst_n) begin
392	    if(!rst_n) begin
393	      threadid           <= 'd0;   
394	      wg_wf_count        <= 'd0;
395	      wf_size_dispatch   <= 'd0;
396	      knl_base           <= 'd0;
397	      wg_id              <= 'd0;
398	      wf_tag_dispatch    <= 'd0;
399	      lds_base_dispatch  <= 'd0;
400	      pds_baseaddr       <= 'd0;
401	      wg_id_x            <= 'd0;
402	      wg_id_y            <= 'd0;
403	      wg_id_z            <= 'd0;
404	      sgpr_base_dispatch <= 'd0;
405	      vgpr_base_dispatch <= 'd0;
406	    end
407	    else if(CTA2csr_valid_i) begin
408	      threadid           <= dispatch2cu_wf_tag_dispatch_i[`DEPTH_WARP-1:0]<<`DEPTH_THREAD;
409	      wg_wf_count        <= dispatch2cu_wg_wf_count_i;
410	      wf_size_dispatch   <= dispatch2cu_wf_size_dispatch_i;
411	      knl_base           <= dispatch2cu_csr_knl_dispatch_i;
412	      wg_id              <= dispatch2cu_wg_id_i;
413	      wf_tag_dispatch    <= dispatch2cu_wf_tag_dispatch_i[`DEPTH_WARP-1:0];
414	      lds_base_dispatch  <= {lds_base_dispatch_h[31:`LDS_ID_WIDTH+1],dispatch2cu_lds_base_dispatch_i};
415	      pds_baseaddr       <= dispatch2cu_pds_base_dispatch_i;
416	      wg_id_x            <= dispatch2cu_wgid_x_dispatch_i;
417	      wg_id_y            <= dispatch2cu_wgid_y_dispatch_i;
418	      wg_id_z            <= dispatch2cu_wgid_z_dispatch_i;
419	      sgpr_base_dispatch <= dispatch2cu_sgpr_base_dispatch_i;
420	      vgpr_base_dispatch <= dispatch2cu_vgpr_base_dispatch_i;
421	    end
422	    else begin
423	      threadid           <= threadid;   
424	      wg_wf_count        <= wg_wf_count;
425	      wf_size_dispatch   <= wf_size_dispatch;
426	      knl_base           <= knl_base;
427	      wg_id              <= wg_id;
428	      wf_tag_dispatch    <= wf_tag_dispatch;
429	      lds_base_dispatch  <= lds_base_dispatch;
430	      pds_baseaddr       <= pds_baseaddr;
431	      wg_id_x            <= wg_id_x;
432	      wg_id_y            <= wg_id_y;
433	      wg_id_z            <= wg_id_z;
434	      sgpr_base_dispatch <= sgpr_base_dispatch;
435	      vgpr_base_dispatch <= vgpr_base_dispatch;
436	    end
437	  end
438	
439	  //float csr address
440	  always @(posedge clk or negedge rst_n) begin
441	    if(!rst_n) begin
442	      nv  <= 'd0;
443	      dz  <= 'd0;
444	      of  <= 'd0;
445	      uf  <= 'd0;
446	      nx  <= 'd0;
447	      frm <= 'd0;
448	    end
449	    else if(wen & csr_addr == `CSR_FFLAGS) begin
450	      nv  <= csr_wdata[4];
451	      dz  <= csr_wdata[3];
452	      of  <= csr_wdata[2];
453	      uf  <= csr_wdata[1];
454	      nx  <= csr_wdata[0];
455	    end
456	    else if(wen & csr_addr == `CSR_FRM) begin
457	      frm <= csr_wdata[2:0];
458	    end
459	    else begin
460	      nv  <= nv;
461	      dz  <= dz;
462	      of  <= of;
463	      uf  <= uf;
464	      nx  <= nx;
465	      frm <= frm;
466	    end
467	  end
468	
469	  always @(*) begin
470	    fflags = {nv,dz,of,uf,nx};
471	    fcsr   = {24'd0,frm,fflags};
472	  end
473	
474	  //Vector csr address
475	  always @(posedge clk or negedge rst_n) begin
476	    if(!rst_n) begin
477	      vill   <= 'd0;
478	      vma    <= 'd0;
479	      vta    <= 'd0;
480	      vsew   <= 'd0;
481	      vlmul  <= 'd0;
482	      vlmax  <= 'd0;
483	      //vstart <= 'd0;
484	      //vxsat  <= 'd0;
485	      //vxrm   <= 'd0;
486	      //vcsr   <= 'd0;
487	      //vl     <= 'd0;
488	      //vlenb  <= 'd0;
489	    end
490	    else begin
491	      vill   <= 'd0;
492	      vma    <= 'd0;
493	      vta    <= 'd0;
494	      vsew   <= 3'd2;
495	      vlmul  <= 'd0;
496	      vlmax  <= `NUM_THREAD;
497	      //vstart <= 'd0;
498	      //vxsat  <= 'd0;
499	      //vxrm   <= 'd0;
500	      //vcsr   <= 'd0;
501	      //vl     <= 'd0;
502	      //vlenb  <= 'd0;
503	    end
504	  end
505	
506	  always @(*) begin
507	    vtype = {vill,23'd0,vma,vta,vsew,vlmul};
508	  end
509	
510	endmodule
511	
512	  
513	  
514	      
515	  
516	
517

